import React from 'react';

const FieldForceManagementDefinition = () => {
    return (
        <section id="fieldForceDefinition" className=" container d-flex flex-column align-items-center" style={{ paddingTop: "40px", paddingBottom: "80px", minHeight: "auto" }}>
            <h2 className="text-center" style={{ fontSize: "35px", fontWeight: "500", paddingBottom: "0px" }}>Field Force Management <span style={{ color: "#609DCE" }}>Platform</span></h2>
            <p className="text-justify pt-4 px-5" style={{ fontSize: "18px", fontWeight: "200", wordSpacing: "5px" }}>This application incorporates cutting-edge technologies to provide advanced scheduling and workforce management solutions that are accessible to the organization. SFFMS provides you with an end-to-end visibility of the field operations and business processes, with native mobile app support across all major mobile platforms for you to know in real-time about your business.</p>
        </section>
    );
};

export default FieldForceManagementDefinition;
